algorithms.pseudocode:
function bin_conv(a[0..N-1], b[0..N-1]) -> c[0..N-1]:
    precompute C[n][i] via Pascal: C[n][0]=C[n][n]=1, C[n][i]=C[n-1][i-1]+C[n-1][i]
    for n in 0..N-1:
        s <- 0
        for i in 0..n:
            s <- s + C[n][i] * a[i] * b[n-i]
        c[n] <- s
    return c

function egf(a[0..N-1]) -> c[0..N-1]:
    f <- 1 ; for n in 0..N-1: c[n] <- a[n]/f ; f <- f*(n+1)
    return c

function seq_of(c[0..N-1]) -> a[0..N-1]:
    f <- 1 ; for n in 0..N-1: a[n] <- f*c[n] ; f <- f*(n+1)
    return a

function bin_conv_pow(a, k) -> result:
    result <- delta = (1,0,0,...)        # convolution unit
    base   <- a
    while k > 0:
        if k is odd: result <- bin_conv(result, base)
        base <- bin_conv(base, base)
        k <- k >> 1
    return result
